import { _ as _export_sfc, o as openBlock, c as createElementBlock, a3 as createStaticVNode } from "./chunks/framework.DVGwMfR6.js";
const __pageData = JSON.parse('{"title":"16. Waste collection, treatment and recycling","description":"","frontmatter":{},"headers":[],"relativePath":"16-waste-treatment-and-recycling.md","filePath":"16-waste-treatment-and-recycling.md"}');
const _sfc_main = { name: "16-waste-treatment-and-recycling.md" };
function _sfc_render(_ctx, _cache, $props, $setup, $data, $options) {
  return openBlock(), createElementBlock("div", null, [..._cache[0] || (_cache[0] = [
    createStaticVNode('<h1 id="_16-waste-collection-treatment-and-recycling" tabindex="-1">16. Waste collection, treatment and recycling <a class="header-anchor" href="#_16-waste-collection-treatment-and-recycling" aria-label="Permalink to &quot;16. Waste collection, treatment and recycling&quot;">​</a></h1><p>This section applies to waste batteries in every battery category, whether or not the battery was subject to a mandatory battery passport. Chapter VIII establishes category-specific collection arrangements and common treatment, recycling and reporting requirements. For these applications GS1 identifiers and EPCIS support interoperable records.</p><h2 id="_16-1-category-specific-collection-systems" tabindex="-1">16.1 Category-specific collection systems <a class="header-anchor" href="#_16-1-category-specific-collection-systems" aria-label="Permalink to &quot;16.1 Category-specific collection systems&quot;">​</a></h2><p>Producers, or producer responsibility organisations where appointed, are responsible for arrangements covering batteries regardless of nature, chemistry, condition, brand or origin within the category.</p><table tabindex="0"><thead><tr><th>Category</th><th>Required action</th><th>Regulatory source</th></tr></thead><tbody><tr><td>Portable, including general-use</td><td>Free, territory-wide separate collection through connected points and delivery to a permitted treatment facility.</td><td>Article 59(1), (2), (4)–(6)</td></tr><tr><td>LMT</td><td>Free, territory-wide separate collection with suitable infrastructure and delivery to permitted facilities.</td><td>Article 60(1), (2), (4)–(7)</td></tr><tr><td>SLI</td><td>Free take-back and separate collection throughout the territory.</td><td>Article 61(1)–(4)</td></tr><tr><td>Industrial, including stationary battery energy storage systems</td><td>Free take-back and separate collection throughout the territory, irrespective of capacity. Where prior dismantling is required at the premises of private, non-commercial users, those users must not bear the dismantling and collection costs.</td><td>Article 61(1)–(4)</td></tr><tr><td>Electric Vehicle</td><td>Free take-back and separate collection throughout the territory.</td><td>Article 61(1)–(4)</td></tr></tbody></table><p>Distributors must take back qualifying waste batteries free of charge without requiring a purchase. The duty is limited to categories that the distributor has or had in its offer and excludes waste products containing batteries. Distance sellers must provide sufficient collection points; delivery sales require a free-return offer and information when ordering (Article 62(1)–(5)). End-users must discard waste batteries separately from other waste, including mixed municipal waste (Article 64(1) and (2)).</p><h2 id="_16-2-collection-targets" tabindex="-1">16.2 Collection targets <a class="header-anchor" href="#_16-2-collection-targets" aria-label="Permalink to &quot;16.2 Collection targets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Category</th><th style="text-align:right;">Minimum collection rate</th><th>Regulatory Source</th></tr></thead><tbody><tr><td>Portable</td><td style="text-align:right;">45% by 31 December 2023; 63% by 31 December 2027; 73% by 31 December 2030</td><td>Article 59(3); Annex XI</td></tr><tr><td>LMT</td><td style="text-align:right;">51% by 31 December 2028; 61% by 31 December 2031</td><td>Article 60(3); Annex XI</td></tr></tbody></table><p>No percentage targets exist for SLI, industrial or EV batteries. The Regulation divides weight collected in a year by average annual weight first made available to end-users during the preceding three years, calculated separately for portable and LMT batteries. The Commission is empowered to adopt delegated acts by 18 August 2027 amending the methods and adapting the targets accordingly (Articles 59(7) and 60(8)); current acts must be checked before configuring calculations (OQ-REG-013).</p><h2 id="_16-3-end-user-information" tabindex="-1">16.3 End-user information <a class="header-anchor" href="#_16-3-end-user-information" aria-label="Permalink to &quot;16.3 End-user information&quot;">​</a></h2><p>Producers or appointed producer responsibility organisations must make available to end-users and distributors, for the battery categories they supply in a Member State, information on end-users&#39; role in waste prevention and in separate collection; good practices for extending use and the possibilities of re-use, preparation for re-use, preparation for repurposing, repurposing and remanufacturing; available collection, take-back, preparation and treatment; safety instructions for handling waste batteries, including lithium risks; the meaning of labels and symbols; and the impact of substances, including from inappropriate discarding (Article 74(1)(a)–(f)). They must provide it at regular intervals for each battery model from first making available in the Member State, as a minimum visibly at the point of sale and through online platforms, in a language or languages determined by the Member State that end-users easily understand.</p><p>Distributors supplying end-users must permanently provide this information in their retail premises, easily accessible and clearly visible, with information on returning waste batteries free of charge. This is limited to the categories they offer or have offered as new batteries, and also applies when they sell through online platforms (Article 74(4)). Producers or producer responsibility organisations must conduct awareness campaigns and offer incentives to encourage correct discarding (Article 74(6)). Commercially sensitive information stays confidential (Article 74(7)).</p><p>Producers must also give distributors and waste operators information on safety and protective measures for storage and collection, and must give operators carrying out preparation or treatment model-specific dismantling and safety information, electronically, free of charge and on request (Article 74(2)–(3)).</p><h2 id="_16-4-handover-and-transaction-records" tabindex="-1">16.4 Handover and transaction records <a class="header-anchor" href="#_16-4-handover-and-transaction-records" aria-label="Permalink to &quot;16.4 Handover and transaction records&quot;">​</a></h2><p>End-of-life vehicle and WEEE treatment-facility operators must hand removed batteries to the relevant producer, producer responsibility organisation or selected waste operator for treatment and keep transaction records.</p><p>An operational record associates date, source, destination, parties, category, chemistry, measured quantity, logistic-unit reference and intended operation. These are implementation data, not invented legal requirements. GLN identifies parties, functions or locations. SSCC identifies the logistic unit (i.e. trade items packed on a pallet or in a container), but should not be used to identify each battery inside.</p><h2 id="_16-5-storage-and-transport" tabindex="-1">16.5 Storage and transport <a class="header-anchor" href="#_16-5-storage-and-transport" aria-label="Permalink to &quot;16.5 Storage and transport&quot;">​</a></h2><p>Collection infrastructure must suit expected volume and hazardous nature and meet applicable safety rules according to regulation. Portable and LMT transport containers must meet Directive 2008/68/EC requirements (Article 59(1)(c); Article 60(1)(c)). At treatment facilities, impermeable surfaces and weatherproof covering or suitable containers are required; batteries must not be mixed with conductive or combustible waste (Annex XII, Part A, points 2 and 3). Lithium-based batteries require heat, water, damage, orientation, ventilation, isolation and warning controls in Annex XII, Part A, point 4.</p><p>Producers must give relevant operators safety information and, from first supply, provide relevant waste operators electronically, free and on request, with model-specific dismantling, storage, transport and treatment information, including components, materials and hazardous-substance locations. GS1 identifiers link to controlled information such as dangerous-goods classification or transport compliance.</p><h2 id="_16-6-treatment-requirements" tabindex="-1">16.6 Treatment requirements <a class="header-anchor" href="#_16-6-treatment-requirements" aria-label="Permalink to &quot;16.6 Treatment requirements&quot;">​</a></h2><p>Separately collected batteries must undergo treatment and not be disposed of or sent to energy recovery. Treatment must occur in a permitted facility, comply with Annex XII, Part A and use best available techniques under Directive 2010/75/EU. It must remove fluids and acids. Mercury and cadmium must each be separately collected into identifiable streams. Batteries must be removed from WEEE, end-of-life vehicles and other waste products during treatment.</p><p>GS1 identification structures form a hierarchy for batteries. GTIN identifies a battery model or trade item; GTIN plus batch or lot number identifies a batch; GTIN plus serial number identifies an instance.</p><h2 id="_16-7-recycling-efficiency-and-material-recovery" tabindex="-1">16.7 Recycling efficiency and material recovery <a class="header-anchor" href="#_16-7-recycling-efficiency-and-material-recovery" aria-label="Permalink to &quot;16.7 Recycling efficiency and material recovery&quot;">​</a></h2><p>Each permitted facility must ensure that all waste batteries made available to it are accepted and undergo preparation for re-use, preparation for repurposing or recycling (Article 71(1)). Recyclers must achieve the following targets (Article 71(2) and (3); Annex XII, Parts B and C):</p><table tabindex="0"><thead><tr><th>Date</th><th>Target by material</th></tr></thead><tbody><tr><td>Efficiency by 31 December 2025</td><td>Lead-acid 75%; lithium-based 65%; nickel-cadmium 80%; other 50% by average weight</td></tr><tr><td>Efficiency by 31 December 2030</td><td>Lead-acid 80%; lithium-based 70% by average weight</td></tr><tr><td>Recovery by 31 December 2027</td><td>Cobalt, copper, lead and nickel 90% each; lithium 50%</td></tr><tr><td>Recovery by 31 December 2031</td><td>Cobalt, copper, lead and nickel 95% each; lithium 80%</td></tr></tbody></table><p>Article 71(4) requires calculation, verification and documentation rules. Commission Delegated Regulation (EU) 2025/606, in force since 24 July 2025, sets them in its Annex:</p><table tabindex="0"><thead><tr><th>Subject</th><th>What the Annex requires</th><th>Annex to Regulation (EU) 2025/606</th></tr></thead><tbody><tr><td>Recycling efficiency</td><td>Recyclers calculate output fractions as a mass percentage of input fractions per calendar year, separately for lead-acid, lithium-based, nickel-cadmium and other batteries. Emissions to air, water and soil do not count. Until 31 December 2029, oxygen, carbon and iron from cell-level sources, phosphorus, chlorine and sulphur may be counted. From 1 January 2030, carbon and iron from cell-level sources and phosphorus shall be counted, while oxygen, chlorine and sulphur may be.</td><td>Sections 1 and 2</td></tr><tr><td>Input composition</td><td>Recyclers determine the share of each chemistry by sorting analysis. They determine overall chemical composition from producer information held in an electronic record, such as the battery passport where one exists, or from analysis of all output fractions plus emissions and waste, or by sampling and analysing the input.</td><td>Section 2</td></tr><tr><td>Material recovery</td><td>For cobalt, copper, lead, lithium and nickel, the rate is the mass of the material in output fractions at the recovery calculation point, as a percentage of its mass in input fractions per calendar year. That point is the step at which the material is recovered in a form that can substitute primary material in manufacturing. Black mass is an intermediate fraction, not an output fraction.</td><td>Sections 1 and 3</td></tr><tr><td>Mercury and cadmium</td><td>The documentation states the input amounts and the amounts safely immobilised and disposed of, and for cadmium also the amount in recycled output fractions.</td><td>Section 4</td></tr><tr><td>Documentation</td><td>Recyclers provide the data every year, broken down by Member State of collection, to the competent authorities of the Member State of treatment, in electronic form using the template for each chemistry. The data cover every recycling facility involved and the corresponding fractions, but not the individual operations within one facility. Where several permitted facilities are involved, the first recycler collects and provides the information, and upstream operators supply it.</td><td>Sections 1, 5 to 9 and 10</td></tr><tr><td>Verification</td><td>The competent authority of the Member State of treatment verifies the overall calculations every calendar year and, for recycling outside the EU, the documentary evidence of equivalent conditions. It may request evidence from parties in the recycling chain and audit them. Recyclers may also self-audit through external companies. For waste holders exporting batteries for treatment, the authority of the Member State where they are located verifies.</td><td>Section 10</td></tr></tbody></table><p>The Annex sets no retention period for this documentation. The Regulation and the delegated act do not prescribe GS1 standards for these calculations. GS1 identifiers and EPCIS events support the underlying source records (see Sections 16.9, 16.10 and 16.10.1); a measured output or a TransformationEvent does not by itself establish a calculated or verified rate.</p><p>The Commission had to assess by 18 August 2026, and must assess at least every five years thereafter, whether to revise the targets in Annex XII, Parts B and C, and may amend them by delegated act (Article 71(5)). Whether that assessment has changed the targets must be checked before they are configured.</p><h2 id="_16-8-regulatory-reporting" tabindex="-1">16.8 Regulatory reporting <a class="header-anchor" href="#_16-8-regulatory-reporting" aria-label="Permalink to &quot;16.8 Regulatory reporting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Reporter</th><th>Minimum scope</th><th>Regulatory source</th></tr></thead><tbody><tr><td>Producers or PROs for portable and LMT</td><td>Market, collection, rate, treatment, export and preparation quantities</td><td>Article 75(1)</td></tr><tr><td>Producers or PROs for SLI, industrial and EV</td><td>Market quantities and collected quantities sent to preparation, treatment or export</td><td>Article 75(2)</td></tr><tr><td>Other collecting waste operators</td><td>Applicable collection and destination quantities</td><td>Article 75(1), second subparagraph, and (3)</td></tr><tr><td>Treatment operators and recyclers</td><td>Received and processed quantities; efficiency; recovery; output destinations and yields</td><td>Article 75(5)</td></tr><tr><td>Other waste holders exporting for treatment</td><td>Exported quantities and applicable treatment data</td><td>Article 75(6)</td></tr></tbody></table><p>Reporting covers every recycling step and output fraction. In multi-facility recycling, the first recycler collects and reports the information. The reports are due within six months; the first period is the first full calendar year after entry into force of the implementing act adopted under Article 76(5). Authorities have to establish electronic systems and formats (Article 75(8) and (9)). The first reporting year is 2026, with reports due by 30 June 2027; see Section 15.9, “Reporting quantities placed on the market”, for the calculation and for national reporting formats. The data recyclers provide under Delegated Regulation (EU) 2025/606 may also be considered for Article 75(5) (Annex, section 5, point 1). GS1 identifiers support source records.</p><h2 id="_16-9-how-gs1-identifiers-support-waste-stream-records" tabindex="-1">16.9 How GS1 identifiers support waste-stream records <a class="header-anchor" href="#_16-9-how-gs1-identifiers-support-waste-stream-records" aria-label="Permalink to &quot;16.9 How GS1 identifiers support waste-stream records&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement or operational need</th><th>GS1 application</th><th>Explanation</th></tr></thead><tbody><tr><td>Identify the battery model or trade item represented in a waste-stream record</td><td>Where the battery is managed as a trade item GTIN identifies the battery model or battery. Associated data records the applicable battery category, chemistry and other required attributes.</td><td>A GTIN needs an additional serial number to identify an individual battery. GTIN plus serial number identifies that battery instance; associated records hold data such as category, chemistry, condition or measured quantity. Where a battery is incorporated in another product, the battery identifier must remain distinguishable from the host-product identifier.</td></tr><tr><td>Distinguish a production batch where waste-stream evidence remains available at batch level</td><td>GTIN plus batch/lot number identifies the relevant battery batch/lot.</td><td>Batch/lot identification supports sorting, investigation and reconciliation. Chapter VIII does not require every waste battery to retain batch-level identity.</td></tr><tr><td>Preserve individual battery identity where it remains available and is needed by the implementation</td><td>GTIN plus serial number identifies an individual battery instance.</td><td>Universal serialisation of waste batteries is not necessary; the serialised GTIN serves other purposes. An unreadable or unavailable serial number must not be reconstructed or inferred, but a GTIN alone cannot be treated as instance-level identification.</td></tr><tr><td>Identify parties, functions and locations involved in collection, handover, storage, treatment or reporting</td><td>GLN identifies the relevant legal entity, organisational function or physical location. Separate GLNs distinguish parties from operational sites.</td><td>Article 65(2) requires specified treatment-facility operators to keep transaction records. A GLN therefore complements a permit, registration number or other authority-issued identifier.</td></tr><tr><td>Identify a pallet, cage, drum, container or other logistic unit used in the waste stream</td><td>SSCC identifies the logistic unit. Governed records associate it with its measured or declared contents and preserve aggregation and separation relationships.</td><td>An SSCC does not identify each battery inside the logistic unit or establish its contents. Mixed streams may support only logistic-unit or consignment identification, and measured quantities must not be inferred from the identifier.</td></tr></tbody></table><p>Implementers select the needed granularity, preserve aggregation and separation associations, and record measured quantities rather than infer them from identifiers. Mixed bulk streams may support only consignment or logistic-unit identification; unavailable instance identity must not be invented.</p><h2 id="_16-10-how-epcis-supports-collection-and-treatment-events" tabindex="-1">16.10 How EPCIS supports collection and treatment events <a class="header-anchor" href="#_16-10-how-epcis-supports-collection-and-treatment-events" aria-label="Permalink to &quot;16.10 How EPCIS supports collection and treatment events&quot;">​</a></h2><p>EPCIS captures events concerning identified batteries, batches, logistic units, parties and locations. ObjectEvent records observations or status changes, while AggregationEvent associates those objects with a parent logistic unit. TransformationEvent captures the relationship between recycling inputs and outputs. GS1 Core Business Vocabulary (CBV) defines terms, definitions and context such as collecting, decommissioning, disassembling and inspecting to be used to store events.</p><p>The design must define event ownership, granularity, aggregation, measurement, corrections, access, confidentiality, retention and reconciliation with Article 75 aggregates. EPCIS supports evidence management; it does not prove permitting, correct treatment or target achievement and does not replace statutory reports, verification, audits or authority decisions.</p><h3 id="_16-10-1-data-for-the-recycling-documentation" tabindex="-1">16.10.1 Data for the recycling documentation <a class="header-anchor" href="#_16-10-1-data-for-the-recycling-documentation" aria-label="Permalink to &quot;16.10.1 Data for the recycling documentation&quot;">​</a></h3><p>Delegated Regulation (EU) 2025/606 requires first recyclers to document recycling in the templates in sections 6 to 9 of its Annex, one for each of lead-acid, lithium-based, nickel-cadmium and other batteries (see Section 16.7). The Regulation and the delegated act do not prescribe GS1 standards. This guideline proposes the published GS1 standards below for the source records behind those templates. The mapping is this guideline&#39;s own: no GS1 source maps these templates. Where no published GS1 term was found, the table says so and proposes none.</p><table tabindex="0"><thead><tr><th>Template field</th><th>Published GS1 standard</th><th>Limitations</th></tr></thead><tbody><tr><td>First recycler, each facility and further operator: name, address and country</td><td>GLN identifies the party or facility. Location and party master data hold the name and address, including the country code.</td><td>The template still requires these details to be written out, together with a contact person. A GLN does not replace them or any authority-issued identifier.</td></tr><tr><td>Calendar year</td><td>The EPCIS event time records when each event occurred.</td><td>The recycler assigns events to the calendar year.</td></tr><tr><td>Individual recycling steps (Part 2)</td><td>TransformationEvent captures the relationship between inputs and outputs, and a shared transformation identifier links events in a longer process. The business location, identified by GLN, shows where the step took place.</td><td>Inputs and outputs need identifiers for the event to link them. The recycler still provides the flow chart or description. No published CBV business step for recycling or preparation for recycling was found. CBV provides the value “other” for steps not yet in the CBV.</td></tr><tr><td>Waste batteries entering recycling: mass</td><td>SSCC identifies the logistic unit received. AI (330n) expresses the logistic weight of that unit. An EPCIS quantity with a unit of measure expresses an amount of an object identified at class level.</td><td>The logistic weight is the gross weight of the whole unit. The template asks for the wet mass of the waste batteries as received, which the recycler has to measure. An identifier does not establish the mass.</td></tr><tr><td>Waste batteries entering recycling: type and chemistry</td><td>GTIN identifies the battery trade item where the battery remains identifiable.</td><td>Waste batteries are often mixed, and the Annex requires a sorting analysis (section 2). No published GS1 Web Vocabulary term for battery chemistry was found, and GDSN coverage has not been verified.</td></tr><tr><td>EWC code</td><td>No published GS1 field was found.</td><td>The recycler records the code outside GS1 standards.</td></tr><tr><td>Member State of collection</td><td>An EPCIS source of type “location” carries the GLN of the collection location, and location master data hold its country code.</td><td>No published GS1 term for this concept was found, so it is derived from the collection location. It is available only where collectors share these events and data.</td></tr><tr><td>Intermediate and output fractions, including black mass, and their element or compound masses</td><td>No published GS1 rule for identifying waste fractions was found.</td><td>A TransformationEvent links only fractions that carry an identifier. Masses of elements and compounds are measured and calculated by the recycler.</td></tr><tr><td>Further operator, and destination and yield of the fractions</td><td>GLN identifies the further operator. EPCIS shipping events with a destination record the handover.</td><td>The recycler measures the yield.</td></tr><tr><td>Recycling-efficiency and material-recovery rates; mercury and cadmium amounts; verification</td><td>None. These are not GS1 functions.</td><td>The first recycler calculates the rates and the competent authority verifies them. GS1 records supply inputs rather than these results.</td></tr></tbody></table><p>Technical basis: GS1 General Specifications, sections 1.3.3, 3.3.1 and 3.6.3, p. 221; GS1 EPCIS Standard, sections 7.3.3.1, 7.3.4, 7.3.5, 7.3.6.4 and 7.4.5, pp. 54–55, 65 and 93; GS1 Core Business Vocabulary Standard, sections 7.1, 7.4 and 9.3, pp. 54 and 117.</p><h2 id="_16-11-mixed-and-damaged-battery-streams" tabindex="-1">16.11 Mixed and damaged battery streams <a class="header-anchor" href="#_16-11-mixed-and-damaged-battery-streams" aria-label="Permalink to &quot;16.11 Mixed and damaged battery streams&quot;">​</a></h2><p>Collection covers batteries regardless of condition, while infrastructure and frequency must reflect volume and hazardous nature (Articles 59(1), 60(1) and (4), and 61(1) and (3)). Annex XII adds lithium precautions and prohibits mixing with conductive or combustible waste.</p><p>SSCC identifies a mixed container, which records associate with measured or estimated content by category and chemistry. After sorting, new logistic units and measured contents can be related to the incoming unit. Damaged, leaking or thermally affected batteries must be segregated and recorded at the level needed for safety and transport controls. If an original label, serial number, QR code or passport identifier is unreadable, an operator must not create an unverified link. A local consignment identifier may preserve custody while recording that original identity is unknown.</p><h2 id="_16-12-shipments-of-used-and-waste-batteries" tabindex="-1">16.12 Shipments of used and waste batteries <a class="header-anchor" href="#_16-12-shipments-of-used-and-waste-batteries" aria-label="Permalink to &quot;16.12 Shipments of used and waste batteries&quot;">​</a></h2><p>Waste batteries or their fractions may be treated outside the Member State concerned or outside the Union, provided that the shipment complies with Regulations (EC) No 1013/2006 and (EC) No 1418/2007 (Article 72(1)). Check the shipment rules that currently apply before relying on these references (OQ-REG-020).</p><p>Waste exported from the Union counts towards the obligations, efficiencies and targets in Articles 70 and 71 only if the exporter provides documentary evidence, approved by the competent authority of destination, that treatment took place in conditions equivalent to those required by the Regulation and in accordance with other Union law on human health and environmental protection (Article 72(3)). The Commission is empowered to set criteria for assessing equivalent conditions by delegated act (Article 72(4)).</p><p>Competent authorities may inspect shipments of used batteries suspected to be waste, and the costs may be charged to the producers of the relevant category, third parties acting for them or other persons arranging the shipment, where the shipment turns out to consist of waste (Article 72(2)). A holder claiming to ship used batteries, not waste batteries, has to have the following available (Annex XIV, points 1, 3 and 4):</p><table tabindex="0"><thead><tr><th>What the holder needs</th><th>Content</th></tr></thead><tbody><tr><td>Invoice and contract</td><td>A copy of the invoice and contract for the sale or transfer of ownership, stating that the batteries are destined for direct re-use and are fully functional</td></tr><tr><td>Evidence of testing</td><td>Copies of the records, such as the certificate of testing, proof of functionality for every battery or fraction in the consignment, and the protocol with the record below</td></tr><tr><td>Declaration</td><td>A declaration by the holder that nothing in the consignment is waste under Article 3, point (1), of Directive 2008/98/EC</td></tr><tr><td>Protection</td><td>Appropriate protection against damage during transport, loading and unloading, in particular sufficient packaging and appropriate stacking</td></tr><tr><td>Testing</td><td>A test of the state of health and an evaluation of the presence of hazardous substances, with the results recorded</td></tr><tr><td>Record on the battery or packaging</td><td>Fixed securely but not permanently, on the unpacked battery or on the packaging so that it can be read without removing the packaging. It states the name of the battery or fraction, its identification number where applicable, the year of production if available, the name and address of the company testing the state of health, the types of test, and the results with their date</td></tr><tr><td>With every load</td><td>A relevant transport document and a declaration of responsibility by the person liable</td></tr></tbody></table><p>The invoice, testing evidence and testing and record steps do not apply where documentary proof shows a business-to-business transfer agreement under which the used battery is sent back to the producer or a third party acting for it for repair under warranty with the intention of re-use. They also do not apply where a battery for professional use is sent for refurbishment or repair under a valid contract, or where it is defective and is sent for root cause analysis, under the conditions in Annex XIV, point 2. Without the required proof and protection, the object is considered waste and the load is presumed to be an illegal shipment (Annex XIV, point 5). The Commission may supplement these requirements by delegated act, in particular on the state of health (Article 72(2)). Article 73 separately sets the evidence that a waste LMT, industrial or EV battery prepared for re-use or repurposing is no longer waste; see Section 17.6, “End-of-waste evidence”.</p><p>The Regulation requires this evidence but does not prescribe GS1 standards. This guideline proposes the following for the records behind it:</p><table tabindex="0"><thead><tr><th>Need</th><th>GS1 application</th><th>Limitations</th></tr></thead><tbody><tr><td>State the identification number of the battery on the record, where applicable (Annex XIV, point 3)</td><td>GTIN plus serial number identifies an individual battery, and GTIN plus batch/lot number identifies a batch</td><td>A GS1 identifier does not show that a battery is used and not waste. It does not replace the record, and an unreadable identifier must not be reconstructed</td></tr><tr><td>Identify the holder and the testing company</td><td>GLN identifies the legal entity or location, with its name and address in the associated data</td><td>The record still has to state the name and address</td></tr><tr><td>Identify the load and its contents</td><td>SSCC identifies the logistic unit, and records hold its contents</td><td>SSCC does not identify the batteries inside</td></tr><tr><td>Record the movement</td><td>EPCIS shipping and receiving events record custody, with transaction references to the invoice and transport document</td><td>Event records do not authorise a shipment or prove equivalent treatment</td></tr></tbody></table><p>Technical basis: GS1 General Specifications, sections 1.3.1.2, 1.3.1.4, 1.3.3 and 1.3.5.1; GS1 EPCIS Standard, version 2.0.1, sections 7.4.2–7.4.3, pp. 78–88.</p>', 54)
  ])]);
}
const _16WasteTreatmentAndRecycling = /* @__PURE__ */ _export_sfc(_sfc_main, [["render", _sfc_render]]);
